876	        // calling req.destroy(): destroying the socket resets the connection
877	        // while the client is still sending, so it would never receive the
878	        // 400 response (only a network failure). The full request is drained,
879	        // then the rejection below produces a complete, readable response.
880	        tooLarge = true;
881	        chunks.length = 0;
882	        return;
883	      }
884	      chunks.push(buf);
885	    });
886	    req.on('end', () => {
887	      if (settled) return;
888	      settled = true;
889	      if (tooLarge) {
890	        reject(new HttpError(400, `request body exceeds the allowed size of ${MAX_BODY_BYTES} bytes`));
891	        return;
892	      }
893	      resolve(Buffer.concat(chunks).toString('utf8'));
894	    });
895	    req.on('error', (error: Error) => {
896	      if (settled) return;
897	      settled = true;
898	      reject(new HttpError(400, `could not read request body: ${error.message}`));
899	    });
900	    req.on('aborted', () => {
901	      if (settled) return;
902	      settled = true;
903	      reject(new HttpError(400, 'request body was not fully received'));
904	    });
