965	    respond(res, 404, { error: 'not found' });
966	    return;
967	  }
968	
969	  if (route === '/') {
970	    if (req.method === 'GET') { respond(res, 200, PAGE, true); return; }
971	    methodNotAllowed(res, 'GET');
972	    return;
973	  }
974	  if (route === '/health') {
