```js
// ---------------------------------------------------------------------------
// 19–22. Request size limit regression (server level): the 5 MiB cap applies
//        to the whole JSON request body in UTF-8 bytes — title, summary,
//        body, version and the JSON structure itself — for both POST and PUT,
//        and identically for Content-Length and chunked transfer. These
//        scenarios talk HTTP directly to the real server; no browser needed.
// ---------------------------------------------------------------------------
const MAX_REQUEST_BYTES = 5 * 1024 * 1024;

// Pads the body so the serialized JSON request is exactly `targetBytes` UTF-8
// bytes, pinning that the limit counts the entire request (title, summary,
// body, version and JSON structure), not just the body text.
function jsonPayloadOfSize(targetBytes, { title = '边界标题', summary = '边界摘要', version } = {}) {
  const base = version === undefined
    ? { title, summary, body: '' }
    : { title, summary, body: '', version };
  const overhead = Buffer.byteLength(JSON.stringify(base), 'utf8');
  const fill = targetBytes - overhead;
  assert.ok(fill >= 0, `JSON 结构本身（${overhead} 字节）不应超过目标大小 ${targetBytes}`);
  const text = JSON.stringify({ ...base, body: 'x'.repeat(fill) });
  assert.equal(Buffer.byteLength(text, 'utf8'), targetBytes);
  return text;
}

// Sends one request to the real server either with an explicit Content-Length
// (`body`) or as chunked transfer without a declared length (`chunks`, sent
// piece by piece), and resolves with the complete response. Both styles must
// produce a fully readable response — never a reset or truncated body.
function sendRaw(server, { method, path, body, chunks }) {
  assert.ok((body === undefined) !== (chunks === undefined), 'body 与 chunks 二选一');
  return new Promise((resolve, reject) => {
    const url = new URL(server.url);
    const headers = { 'content-type': 'application/json', accept: 'application/json' };
    if (chunks) headers['transfer-encoding'] = 'chunked';
    else headers['content-length'] = Buffer.byteLength(body, 'utf8');
    const req = request({
      hostname: url.hostname,
      port: url.port,
      path,
      method,
      headers,
    }, (res) => {
      const parts = [];
      res.on('data', (part) => parts.push(part));
      res.on('end', () => resolve({
        status: res.statusCode,
        headers: res.headers,
        body: Buffer.concat(parts).toString('utf8'),
      }));
      res.on('error', reject);
    });
    req.on('error', reject);
    if (chunks) for (const chunk of chunks) req.write(chunk);
    else req.write(body);
    req.end();
  });
}

// An oversize rejection must be a complete, parseable 400 whose non-empty
// error states the size limit — not a dropped connection or partial body.
function assertOversizeRejected(res) {
  assert.equal(res.status, 400, `超限请求应返回 400，实际 ${res.status}`);
  const declared = Number(res.headers['content-length']);
  assert.ok(Number.isFinite(declared) && declared > 0, '400 响应必须声明完整长度');
  assert.equal(Buffer.byteLength(res.body, 'utf8'), declared, '400 响应体必须完整可读，不能残缺');
  const data = JSON.parse(res.body); // 响应必须可解析
  assert.ok(typeof data.error === 'string' && data.error.length > 0, '400 必须带非空 error');
  assert.match(data.error, /exceed|超过/i, 'error 必须明确说明超过允许大小');
  return data;
}
```

